        hots.length = 0;
        const bx = DOS.x, by = DOS.y, bw = DOS.w, bh = DOS.h;
        chip(ctx, bx, by, bw, bh, SL.panel2, SL.gold);
        const kn = clubKnow(p, dossier.id);
        /* their colours own the spine — the one place a rival brands our slate */
        ctx.fillStyle = club.c1; rr(ctx, bx, by + 10, 4, bh - 20, 2); ctx.fill();
        btn(ctx, 'dos-close', bx + bw - 72, by + 8, 60, 48, '✕ BACK', () => {
          dossier = null;
        }, { px: 12 });
