        chip(ctx, bx + 92, by + 74, 90, 8, club.c1);
        chip(ctx, bx + 186, by + 74, 60, 8, club.c2);
        fogMeter(ctx, kn, bx + 520, by + 8, 336, { h: 60 });
        /* tabs — three, all 48 tall, all thumb-sized */
