        if (post.shown >= r2.lines.length)
          label(ctx, 'TOTAL  +' + r2.coins + ' 🪙', 60, 432 + r2.lines.length * 22 + 6, 15, SL.gold);
        /* what the players took from it — the RPG beat, off real numbers */
        const gains = (r2.xpGains || []).filter(g2 => g2.gain > 8)
          .sort((a2, b2) => b2.gain - a2.gain).slice(0, 4);
        label(ctx, 'EXPERIENCE', 620, 442, 12, SL.dim);
